// Mechanically derive the exception table from raw probe TSVs.
// Applies the rule set derived by probing, and reports every deviation.
import { readFileSync, readdirSync } from 'node:fs';

const PY_WS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
  0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);
const isWs = (ch) => PY_WS.has(ch.codePointAt(0));
function pyStrip(s) {
  const cps = Array.from(s);
  let i = 0, j = cps.length;
  while (i < j && isWs(cps[i])) i++;
  while (j > i && isWs(cps[j - 1])) j--;
  return cps.slice(i, j).join('');
}
const CASED = /\p{Cased}/u;
function pyTitle(s) {
  let out = '', prevCased = false;
  for (const ch of s) {
    out += prevCased ? ch.toLowerCase() : ch.toUpperCase();
    prevCased = CASED.test(ch);
  }
  return out;
}
function matchCase(master, disciple) {
  if (master.toLowerCase() === master) return disciple.toLowerCase();
  if (master.toUpperCase() === master) return disciple.toUpperCase();
  if (pyTitle(master) === master) return pyTitle(disciple);
  return disciple;
}
function ruleOnly(orig) {
  const word = pyStrip(orig).toLowerCase();
  if (!word) return orig;
  const cps = Array.from(word);
  let plural;
  const prev = cps.length >= 2 ? cps[cps.length - 2] : '';
  if (word.endsWith('y') && !'aeiou'.includes(prev)) plural = cps.slice(0, -1).join('') + 'ies';
  else if (word.endsWith('es')) plural = word;
  else if (word.endsWith('s') || word.endsWith('ch') || word.endsWith('sh')) plural = word + 'es';
  else plural = word + 's';
  return matchCase(orig, plural);
}

const rows = new Map();
for (const f of readdirSync('/tmp/probe/data').filter((f) => f.endsWith('.tsv'))) {
  for (const line of readFileSync(`/tmp/probe/data/${f}`, 'utf8').split('\n')) {
    if (!line) continue;
    const parts = line.split('\t');
    if (parts.length < 2) continue;
    const [w, p] = parts;
    if (rows.has(w) && rows.get(w).p !== p) console.error(`CONFLICT ${JSON.stringify(w)}: ${rows.get(w).p} vs ${p} (${f})`);
    rows.set(w, { p, f });
  }
}

const identity = [], mapped = [], weird = [];
for (const [w, { p }] of rows) {
  const pred = ruleOnly(w);
  if (pred === p) continue;
  if (p === w) identity.push(w);                        // returned verbatim => already-plural set
  else {
    // does it look like matchCase(w, X) for some lowercase X?
    const lw = pyStrip(w).toLowerCase();
    if (matchCase(w, p.toLowerCase()) === p && p.toLowerCase() !== lw) mapped.push([lw, p.toLowerCase()]);
    else weird.push([w, p, pred]);
  }
}
const uniq = (a) => [...new Set(a)].sort();
const mapObj = {};
for (const [k, v] of mapped) {
  if (mapObj[k] && mapObj[k] !== v) console.error(`MAP CONFLICT ${k}: ${mapObj[k]} vs ${v}`);
  mapObj[k] = v;
}
console.log(`probed=${rows.size} rulePredicted=${rows.size - identity.length - mapped.length - weird.length}`);
console.log(`\n=== IRREGULAR MAP (${Object.keys(mapObj).length}) ===`);
console.log(JSON.stringify(mapObj, null, 0));
console.log(`\n=== IDENTITY / already-plural returns (${uniq(identity).length}) ===`);
console.log(JSON.stringify(uniq(identity)));
console.log(`\n=== UNEXPLAINED (${weird.length}) ===`);
for (const [w, p, pred] of weird.slice(0, 80)) console.log(`  ${JSON.stringify(w)} -> got ${JSON.stringify(p)} predicted ${JSON.stringify(pred)}`);

