/**
 * pystring.mjs — CPython `str` semantics that JavaScript does not provide natively.
 *
 * The reference implementation lower-cases, strips and title-cases the unit noun before
 * inflecting it, so the port has to reproduce those three operations exactly:
 *
 *   - `str.strip()` removes every character for which `str.isspace()` is true. That set is
 *     neither ASCII whitespace nor `String.prototype.trim()`'s set: CPython strips the file
 *     separators U+001C..U+001F and NEL (U+0085), while `trim()` does not, and `trim()` strips
 *     the BOM (U+FEFF), which CPython does not.
 *   - `str.title()` title-cases a character only when the *previous* character was not "cased",
 *     using the Unicode Titlecase_Mapping (not the uppercase mapping).
 *   - `str.lower()` / `str.upper()` match `toLowerCase()` / `toUpperCase()` on their own, since
 *     both implement the unconditional Unicode full case mappings (ß→SS, İ→i̇, final sigma …).
 */

/** Code points where CPython's `str.isspace()` is true. */
const PY_WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, // \t \n \v \f \r
  0x1c, 0x1d, 0x1e, 0x1f, // file/group/record/unit separators
  0x20, // space
  0x85, // NEL
  0xa0, // NBSP
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, // LINE / PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

/** True when `ch` is whitespace for CPython (`str.isspace()`). */
export function isPySpace(ch) {
  return PY_WHITESPACE.has(ch.codePointAt(0));
}

/** `str.strip()` — remove leading and trailing CPython whitespace. */
export function pyStrip(s) {
  const chars = Array.from(s);
  let start = 0;
  let end = chars.length;
  while (start < end && isPySpace(chars[start])) start += 1;
  while (end > start && isPySpace(chars[end - 1])) end -= 1;
  return chars.slice(start, end).join('');
}

/** `str.lower()`. */
export function pyLower(s) {
  return s.toLowerCase();
}

/** `str.upper()`. */
export function pyUpper(s) {
  return s.toUpperCase();
}

const CASED = /\p{Cased}/u;
const CASE_IGNORABLE = /\p{Case_Ignorable}/u;

/** Unicode "Cased" property — what CPython's `_PyUnicode_IsCased()` tests. */
export function isCased(ch) {
  return CASED.test(ch);
}

/**
 * Characters whose Unicode Titlecase_Mapping differs from their Uppercase_Mapping.
 * `toUpperCase()` cannot stand in for title-casing these.
 */
const TITLE_EXCEPTIONS = new Map([
  // Latin digraphs: uppercase is the all-caps form, titlecase the mixed form.
  ['Ǆ', 'ǅ'], ['ǅ', 'ǅ'], ['ǆ', 'ǅ'],
  ['Ǉ', 'ǈ'], ['ǈ', 'ǈ'], ['ǉ', 'ǈ'],
  ['Ǌ', 'ǋ'], ['ǋ', 'ǋ'], ['ǌ', 'ǋ'],
  ['Ǳ', 'ǲ'], ['ǲ', 'ǲ'], ['ǳ', 'ǲ'],
  // SpecialCasing.txt entries whose title form only capitalises the first letter.
  ['ß', 'Ss'], // ß
  ['ﬀ', 'Ff'], ['ﬁ', 'Fi'], ['ﬂ', 'Fl'],
  ['ﬃ', 'Ffi'], ['ﬄ', 'Ffl'], ['ﬅ', 'St'], ['ﬆ', 'St'],
  ['և', 'Եւ'], // և
  ['ﬓ', 'Մն'], ['ﬔ', 'Մե'], ['ﬕ', 'Մի'],
  ['ﬖ', 'Ւն'], ['ﬗ', 'Մխ'],
]);

// Greek letters with ypogegrammeni: uppercase decomposes to base + capital iota, while the
// titlecase mapping is the precomposed capital-with-prosgegrammeni character.
for (let base = 0x1f80; base <= 0x1fa7; base += 1) {
  if (base >= 0x1f88 && base <= 0x1f8f) continue;
  if (base >= 0x1f98 && base <= 0x1f9f) continue;
  TITLE_EXCEPTIONS.set(String.fromCodePoint(base), String.fromCodePoint(base + 8));
}
for (const cp of [0x1f88, 0x1f89, 0x1f8a, 0x1f8b, 0x1f8c, 0x1f8d, 0x1f8e, 0x1f8f,
  0x1f98, 0x1f99, 0x1f9a, 0x1f9b, 0x1f9c, 0x1f9d, 0x1f9e, 0x1f9f,
  0x1fa8, 0x1fa9, 0x1faa, 0x1fab, 0x1fac, 0x1fad, 0x1fae, 0x1faf,
  0x1fbc, 0x1fcc, 0x1ffc]) {
  TITLE_EXCEPTIONS.set(String.fromCodePoint(cp), String.fromCodePoint(cp));
}
TITLE_EXCEPTIONS.set('ᾳ', 'ᾼ');
TITLE_EXCEPTIONS.set('ῃ', 'ῌ');
TITLE_EXCEPTIONS.set('ῳ', 'ῼ');

/** Titlecase one character the way `_PyUnicode_ToTitleFull()` does. */
function titleChar(ch) {
  const mapped = TITLE_EXCEPTIONS.get(ch);
  return mapped === undefined ? ch.toUpperCase() : mapped;
}

const CAPITAL_SIGMA = 'Σ';
const FINAL_SIGMA = 'ς';

/**
 * Lower-case one character in context. Only Σ is context sensitive: it becomes ς when it ends a
 * word. `toLowerCase()` applies that rule to whole strings, but we lower character by character
 * (that is what CPython's title() does), so the condition has to be evaluated by hand.
 */
function lowerCharInContext(chars, index) {
  const ch = chars[index];
  if (ch !== CAPITAL_SIGMA) return ch.toLowerCase();
  let precededByCased = false;
  for (let i = index - 1; i >= 0; i -= 1) {
    if (CASE_IGNORABLE.test(chars[i])) continue;
    precededByCased = CASED.test(chars[i]);
    break;
  }
  let followedByCased = false;
  for (let i = index + 1; i < chars.length; i += 1) {
    if (CASE_IGNORABLE.test(chars[i])) continue;
    followedByCased = CASED.test(chars[i]);
    break;
  }
  return precededByCased && !followedByCased ? FINAL_SIGMA : 'σ';
}

/**
 * `str.title()` — title-case the first cased character of each run of cased characters and
 * lower-case the rest. "Previous character was cased" is evaluated on the *input* character,
 * which is why combining marks split a run: 'İstanbul'.title() == 'İstanbul' but
 * 'i̇stanbuls'.title() == 'İStanbuls' (the combining dot is not cased, so the 's' after it
 * starts a new run).
 */
export function pyTitle(s) {
  const chars = Array.from(s);
  let result = '';
  let previousIsCased = false;
  for (let i = 0; i < chars.length; i += 1) {
    const ch = chars[i];
    result += previousIsCased ? lowerCharInContext(chars, i) : titleChar(ch);
    previousIsCased = isCased(ch);
  }
  return result;
}

