/**
 * argparse.mjs — the slice of Python's `argparse` that the reference program exercises.
 *
 * Only what `ArgumentParser` actually does for this CLI is modelled, but it is modelled
 * faithfully: option prefix matching, `--opt=value`, the `--` separator, the negative-number
 * heuristic, help/usage layout, message wording, and the order in which errors are raised
 * (a value-less option beats a missing required option, which in turn beats unrecognized
 * arguments).
 */

import { writeStdout, writeStderr } from './sysio.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class SystemExit extends Error {
  constructor(status) {
    super(`SystemExit: ${status}`);
    this.status = status;
  }
}

/** One `add_argument()` registration. */
class Action {
  constructor(optionStrings, { dest, help = '', required = false, metavar, nargs = 1 }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.help = help;
    this.required = required;
    this.metavar = metavar;
    this.nargs = nargs; // 0 for flags such as --help, 1 for `type=str` options
  }

  /** argparse's `_get_action_name()`: how the action is named inside error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

