const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** Raised instead of calling `process.exit()` so the entry point controls the exit path. */
export class SystemExit extends Error {
  constructor(status) {
    super(`SystemExit: ${status}`);
    this.name = 'SystemExit';
    this.status = status;
  }
