/**
 * sysio.mjs — byte-faithful process I/O.
 *
 * Two details of the CPython runtime matter for character-by-character output equality:
 *
 *  1. CPython decodes `sys.argv` with the `surrogateescape` error handler, so a byte sequence
 *     that is not valid UTF-8 survives as lone surrogates and is written back out unchanged.
 *     Node decodes `process.argv` lossily (invalid bytes become U+FFFD), so the raw bytes are
 *     recovered from `/proc/self/cmdline` when it is available.
 *  2. `print()` writes through a synchronous, unbuffered-at-exit stream. `fs.writeSync` gives
 *     the same guarantee; `process.stdout.write` can lose data when the process exits early.
 */

import { readFileSync, writeSync } from 'node:fs';

const SURROGATE_BASE = 0xdc00;
const SURROGATE_LOW = 0xdc80;
const SURROGATE_HIGH = 0xdcff;

/** Decode UTF-8 the way CPython's `surrogateescape` handler does. */
export function decodeSurrogateEscape(buffer) {
  let result = '';
  let i = 0;
  while (i < buffer.length) {
    const lead = buffer[i];
    if (lead < 0x80) {
      result += String.fromCharCode(lead);
      i += 1;
      continue;
    }
    let length = 0;
    let codePoint = 0;
    let minimum = 0;
    if (lead >= 0xc2 && lead <= 0xdf) {
      length = 2; codePoint = lead & 0x1f; minimum = 0x80;
    } else if (lead >= 0xe0 && lead <= 0xef) {
      length = 3; codePoint = lead & 0x0f; minimum = 0x800;
    } else if (lead >= 0xf0 && lead <= 0xf4) {
      length = 4; codePoint = lead & 0x07; minimum = 0x10000;
    } else {
      result += String.fromCharCode(SURROGATE_BASE + lead);
      i += 1;
      continue;
    }
    let valid = i + length <= buffer.length;
    for (let k = 1; valid && k < length; k += 1) {
      const continuation = buffer[i + k];
      if ((continuation & 0xc0) !== 0x80) valid = false;
      else codePoint = (codePoint << 6) | (continuation & 0x3f);
    }
    if (!valid || codePoint < minimum || codePoint > 0x10ffff
      || (codePoint >= 0xd800 && codePoint <= 0xdfff)) {
      result += String.fromCharCode(SURROGATE_BASE + lead);
      i += 1;
      continue;
    }
    result += String.fromCodePoint(codePoint);
    i += length;
  }
  return result;
}

/** Encode a string back to bytes, turning `surrogateescape` surrogates into their raw byte. */
export function encodeSurrogateEscape(text) {
  const chunks = [];
  let plain = '';
  for (const char of text) {
    const codePoint = char.codePointAt(0);
    if (codePoint >= SURROGATE_LOW && codePoint <= SURROGATE_HIGH) {
      if (plain !== '') {
        chunks.push(Buffer.from(plain, 'utf8'));
        plain = '';
      }
      chunks.push(Buffer.from([codePoint - SURROGATE_BASE]));
    } else {
      plain += char;
    }
  }
  if (plain !== '') chunks.push(Buffer.from(plain, 'utf8'));
  return Buffer.concat(chunks);
}

/**
 * The command-line arguments after the script path, byte-exactly.
 * Falls back to `process.argv` when `/proc/self/cmdline` is unreadable or does not line up.
 */
export function getArgv() {
  const decoded = process.argv.slice(2);
  try {
    const raw = readFileSync('/proc/self/cmdline');
    const tokens = [];
    let start = 0;
    for (let i = 0; i < raw.length; i += 1) {
      if (raw[i] === 0) {
        tokens.push(raw.subarray(start, i));
        start = i + 1;
      }
    }
    if (start < raw.length) tokens.push(raw.subarray(start, raw.length));
    // The user's arguments are always the final `decoded.length` tokens: the interpreter,
    // its own options and the script path all come first.
    if (tokens.length >= decoded.length) {
      const tail = tokens.slice(tokens.length - decoded.length);
      return tail.map((token) => decodeSurrogateEscape(token));
    }
  } catch {
    // /proc is not mounted (or not Linux) — the lossy decoding is the best available.
  }
  return decoded;
}

function writeAll(fd, buffer) {
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue;
      if (error.code === 'EPIPE') return;
      throw error;
    }
  }
}

export function writeStdout(text) {
  writeAll(1, encodeSurrogateEscape(text));
}

export function writeStderr(text) {
  writeAll(2, encodeSurrogateEscape(text));
}

/** `print(value)` — the value followed by a single newline. */
export function print(text) {
  writeStdout(`${text}\n`);
}

